with valid as (select id, account_id, txn_type, amount, txn_time, is_flagged, round(amount * 100, 2) as adjusted_amount, hour(txn_time) as txn_time_hour, coalesce(merchant, 'NONE') as merchant_filled from transactions where merchant is not null and txn_time >= date '2023-06-16') select case when amount >= 4300 then 'HIGH' else 'LOW' end as amount_tier, min(txn_time) as first_seen, round(avg(adjusted_amount), 2) as avg_adjusted_amount from valid group by case when amount >= 4300 then 'HIGH' else 'LOW' end order by amount_tier desc;
